const rows = $input.all().map((item) => item.json);
if (!rows.length) return [];

const groups = new Map();
for (const row of rows) {
  const key = String(row.campaign_id) + '::' + String(row.doctor_id);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(row);
}

const output = [];
for (const group of groups.values()) {
  group.sort((a, b) => Number(a.topic_sort_order) - Number(b.topic_sort_order));
  if (group.length !== 3) throw new Error('Expected exactly three topic links per recipient.');
  const first = group[0];
  if (group.some((row) => row.doctor_id !== first.doctor_id || row.campaign_id !== first.campaign_id)) {
    throw new Error('Invitation rows were grouped incorrectly.');
  }

  const preview = first.preview_only === true || String(first.preview_only).toLowerCase() === 'true';
  const lines = preview
    ? [
        'Hello ' + first.doctor_name + ',',
        '',
        'You are invited to preview Apex Dental Partners\' new AI content interview experience.',
        '',
        'Choose whichever of the three topics below you would most like to discuss, then use its secure link to try a short voice interview:',
        ''
      ]
    : [
        'Hello ' + first.doctor_name + ',',
        '',
        'We have three article topics for you to choose from. Pick the one you would most like to discuss, then use its secure link to start a voice interview:',
        ''
      ];

  for (const row of group) lines.push(row.topic_sort_order + '. ' + row.topic_title, row.interview_url, '');

  lines.push(
    'Before you begin, choose a quiet place. Background conversations and other noise can interrupt the voice interviewer. Headphones with a microphone may help.',
    ''
  );

  if (preview) {
    lines.push('This presentation preview saves the interview transcript for evaluation, but it will not generate or publish an article.', '');
  }

  lines.push('These links expire in 30 days. Please do not include patient-identifying information in the interview.', '', 'Apex Dental Partners');

  output.push({ json: {
    doctor_id: first.doctor_id,
    article_id: '',
    campaign_id: first.campaign_id,
    communication_type: 'CAMPAIGN_INVITATION',
    subject: preview ? 'Preview Apex\'s AI content interview: ' + first.campaign_name : 'Choose your article topic: ' + first.campaign_name,
    message_text: lines.join(String.fromCharCode(10)),
    action_url: ''
  }});
}
return output;

return $input.all()
  .map((item) => item.json)
  .filter((row) => row.status === 'SENT' && row.campaign_id && row.doctor_id)
  .map((row) => ({ json: { campaign_id: row.campaign_id, doctor_id: row.doctor_id } }));

